
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_x_b86_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_x_b86", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.314139320495395e+00, -4.232632654963433e+00, -4.118546192956720e+00, -3.960768732805493e+00, -3.746326329136257e+00, -3.462079032625131e+00, -3.098649618596018e+00, -2.657342979590011e+00, -2.158422971829402e+00, -1.638565473593658e+00, -1.111738247814656e+00, -7.128167899623086e-01, -6.030594193274867e-01, -5.037223215479238e-01, -3.749991013806181e-01, -2.500552989118172e-01, -1.416198665675909e-01, -5.377114154086111e-02, -1.178751956974143e-02, -1.326219765947855e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


